'use strict';
// UI-only synthetic capture controller. No microphone, upload or provider requests.
let activeConsultationCapture=null, pendingConsultationReplacement=null;
function consultationState(){const p=currentPatient();state.consultationUi=state.consultationUi||{};return state.consultationUi[p.id]||(state.consultationUi[p.id]={identityChecked:false,elapsed:0,reviewed:false,paused:false});}
function consultationReady(){const c=consultationState();return c.identityChecked&&state.consent;}
function canPrepareConsultationDraft(){return consultationReady()&&state.captured&&consultationState().reviewed&&state.settings.ai;}
function consultationStage(){return state.note.trim()?3:state.captured?2:consultationReady()?1:0;}
function consultationJourney(){const active=consultationStage();return `<ol class="consultation-journey" aria-label="Consultation progress">${[['Prepare','Check patient & consent'],['Capture','Conversation source'],['Review source','Check the transcript'],['Document','Draft, review & sign']].map(([title,sub],i)=>`<li ${active===i?'aria-current="step"':''} class="${active===i?'current':''}"><span class="journey-index">${i+1}</span><span><strong>${title}</strong><small>${sub}</small></span></li>`).join('')}</ol>`;}
function setConsultationIdentity(checked){if(!checked)stopConsultationCapture(false);consultationState().identityChecked=checked;if(!checked)consultationState().reviewed=false;pendingConsultationReplacement=null;save();render();}
function setConsultationConsent(checked){if(!checked)stopConsultationCapture(false);state.consent=checked;if(!checked)consultationState().reviewed=false;pendingConsultationReplacement=null;audit(state.selectedPatientId+': fictional recording consent '+(checked?'recorded.':'withdrawn; capture stopped.'));render();}
function startConsultationCapture(){
 if(!consultationReady())return toast('Check the patient identity and record consent first.');
 if(!state.settings.speech)return toast('Example transcription is off. Enable it in workspace settings.');
 if(state.captured)return toast('This example is complete. Reset capture before starting again.');
 if(activeConsultationCapture)return;
 const c=consultationState();const patientId=state.selectedPatientId;
 activeConsultationCapture=patientId;recording=true;c.paused=false;c.reviewed=false;seconds=c.elapsed;
 audit(patientId+': synthetic capture '+(c.elapsed?'resumed.':'started.'));render();
 recordTimer=setInterval(()=>{
  if(activeConsultationCapture!==patientId||state.selectedPatientId!==patientId)return;
  if(!state.consent||!consultationState().identityChecked){stopConsultationCapture();return;}
  c.elapsed++;seconds=c.elapsed;save();
  const timer=document.getElementById('consultation-timer');if(timer)timer.textContent=formatTime(c.elapsed);
 },1000);
}
function stopConsultationCapture(redraw=true){
 if(!activeConsultationCapture)return;
 const id=activeConsultationCapture;clearInterval(recordTimer);activeConsultationCapture=null;recording=false;
 const c=state.consultationUi?.[id];if(c)c.paused=true;
 audit(id+': synthetic capture paused.');if(redraw)render();
}
function finishConsultationCapture(){if(!consultationReady()||!state.settings.speech)return toast('Complete preparation and enable example transcription first.');stopConsultationCapture(false);const c=consultationState();c.paused=false;c.reviewed=false;state.captured=true;audit(state.selectedPatientId+': scripted transcript loaded for review. No audio was captured.');render();}
function setConsultationSourceReview(checked){if(!state.captured||!consultationReady())return;consultationState().reviewed=checked;pendingConsultationReplacement=null;save();render();}
function resetConsultationCapture(){const id=state.selectedPatientId;stopConsultationCapture(false);render();modal('Reset the example capture?',`<p>The capture timer and source-review confirmation for <strong>${esc(currentPatient().name)}</strong> will reset.</p><p>The existing document and its version history will be kept. No audio file exists in this development workspace.</p>`,`<button onclick="closeModal()">Keep capture</button><button class="primary" onclick="confirmConsultationReset('${id}')">Reset capture</button>`);}
function confirmConsultationReset(patientId){if(patientId!==state.selectedPatientId)return toast('The active patient changed. Open a fresh reset request.');stopConsultationCapture(false);const c=consultationState();c.elapsed=0;c.paused=false;c.reviewed=false;state.captured=false;seconds=0;pendingConsultationReplacement=null;audit(patientId+': synthetic capture reset; documents retained.');closeModal();render();}
function prepareConsultationDraft(){
 if(state.signed){nav('N');return toast('The reviewed document is protected. Create an amendment in the editor if needed.');}
 if(!canPrepareConsultationDraft())return toast('Complete preparation, load and review the source, and enable example drafting first.');
 if(state.note.trim()){
  pendingConsultationReplacement={patientId:state.selectedPatientId,note:state.note,revision:state.revision,version:state.version};
  modal('A draft already exists',`<p><strong>${esc(currentPatient().name)}</strong> already has an unsigned document. Open it to continue editing, or save a history copy and replace it with the scripted example.</p><p class="fine">Replacement uses the predefined source. It does not call an AI provider.</p>`,`<button onclick="pendingConsultationReplacement=null;closeModal()">Cancel</button><button onclick="pendingConsultationReplacement=null;closeModal();nav('N')">Open existing draft</button><button class="primary" onclick="confirmConsultationReplacement()">Save copy & replace</button>`);return;
 }
 draftNote();
}
function confirmConsultationReplacement(){
 const pending=pendingConsultationReplacement;
 if(!pending||pending.patientId!==state.selectedPatientId||pending.note!==state.note||pending.revision!==state.revision||pending.version!==state.version||state.signed||!canPrepareConsultationDraft())return toast('The draft or preparation changed. Start a fresh draft request.');
 state.history.unshift({patientId:state.selectedPatientId,version:state.version,text:state.note,status:'Draft saved before example replacement',at:new Date().toISOString()});
 pendingConsultationReplacement=null;closeModal();draftNote();
}
const consultationPriorPause=pauseRecord;
pauseRecord=function(){if(activeConsultationCapture)stopConsultationCapture();else consultationPriorPause();};
const consultationPriorSelect=selectPatient;
selectPatient=function(id){if(!demoPatients.some(p=>p.id===id))return;stopConsultationCapture(false);pendingConsultationReplacement=null;consultationPriorSelect(id);seconds=consultationState().elapsed;};
// Reloads never resume capture automatically; elapsed time remains patient-specific.
if(state.consultationUi)for(const [id,c] of Object.entries(state.consultationUi)){if(c.elapsed&&!state.patientRecords[id]?.captured)c.paused=true;}
function consultationStateLabel(){return activeConsultationCapture?'Capture example running':state.captured?'Source ready for review':consultationState().paused?'Capture paused':consultationReady()?'Ready to capture':'Preparation required';}
uiWorkflowFunctions.C=function(){
 const p=currentPatient(),c=consultationState(),running=activeConsultationCapture===p.id;
 const sourceStatus=c.reviewed?'Reviewed locally':state.captured?'Review required':'Awaiting source';
 return consultationJourney()+`<div class="consultation-layout"><section class="consultation-main"><div class="panel prepare-panel"><div class="panel-head"><div><span class="eyebrow">01 / PREPARE</span><h2>Before the conversation</h2></div><span class="pill ${consultationReady()?'green':'amber'}">${consultationReady()?'Ready':'Checks required'}</span></div><div class="preparation-context"><span>Patient priority</span><strong>${p.priority}</strong><button class="text-btn" onclick="nav('E')">View full context ${icon('arrow')}</button></div><label class="preparation-check"><input type="checkbox" id="consultation-identity" ${c.identityChecked?'checked':''} onchange="setConsultationIdentity(this.checked)"><span><strong>Confirm the selected patient</strong><small>${p.name} · ${p.id}. Identity check is a local example.</small></span></label><label class="preparation-check"><input type="checkbox" id="consultation-consent" ${state.consent?'checked':''} onchange="setConsultationConsent(this.checked)"><span><strong>Record consent for the conversation</strong><small>I have explained the process and recorded the fictional patient’s consent.</small></span></label><p class="preparation-note">Withdrawing consent pauses capture immediately. It does not delete existing documents.</p></div><div class="panel capture-panel"><div class="panel-head"><div><span class="eyebrow">02 / CAPTURE</span><h2>Consultation capture</h2></div><span class="pill grey">Local example</span></div><div class="capture-device"><span class="device-symbol">${icon('mic')}</span><div><strong>Microphone & transcription</strong><span>Not connected · No audio is recorded</span></div><button class="text-btn" onclick="nav('connections')">Set up ${icon('arrow')}</button></div><div class="capture-stage ${running?'is-running':''}"><span class="capture-state"><span class="capture-indicator"></span>${consultationStateLabel()}</span><div id="consultation-timer" class="capture-timer" role="timer" aria-label="Elapsed example capture time">${formatTime(c.elapsed)}</div><div class="capture-bars ${running?'is-running':''}" aria-hidden="true">${Array.from({length:32},(_,i)=>`<span style="height:${10+Math.abs(Math.sin(i*1.7))*31}px;animation-delay:${i%7/8}s"></span>`).join('')}</div><p>Elapsed example time · Scripted conversation only</p><div class="capture-actions">${running?'<button class="pause-capture" onclick="stopConsultationCapture()">Pause capture</button><button class="primary" onclick="finishConsultationCapture()">Finish & review source</button>':state.captured?'<button onclick="resetConsultationCapture()">Reset example capture</button>':`<button class="primary" ${!consultationReady()||!state.settings.speech?'disabled':''} onclick="startConsultationCapture()">${icon('play')} ${c.paused?'Resume example':'Start capture example'}</button>${c.paused?'<button onclick="finishConsultationCapture()">Finish & review source</button>':''}`}</div></div>${!state.captured?`<div class="capture-alternative"><button class="text-btn" ${!consultationReady()||!state.settings.speech?'disabled':''} onclick="finishConsultationCapture()">Load example transcript without running capture ${icon('arrow')}</button>${c.elapsed&&!running?'<button class="text-btn" onclick="resetConsultationCapture()">Reset</button>':''}</div>`:''}${!consultationReady()?'<div class="capture-hint">Complete the patient and consent checks above to enable the capture example.</div>':!state.settings.speech?'<div class="capture-hint">Example transcription is switched off. <button class="text-btn" onclick="nav(\'settings\')">Open settings</button></div>':''}</div></section><aside class="consultation-source"><div class="panel consultation-transcript"><div class="panel-head"><div><span class="eyebrow">03 / REVIEW SOURCE</span><h2>Conversation transcript</h2></div><span class="pill ${c.reviewed?'green':state.captured?'amber':'grey'}">${sourceStatus}</span></div>${state.captured?`<div class="transcript-source-label">${p.id} · Predefined example · No audio playback</div><div class="consultation-transcript-body">${transcriptMarkup()}</div><label class="preparation-check source-review"><input type="checkbox" id="consultation-source-reviewed" ${c.reviewed?'checked':''} ${!consultationReady()?'disabled':''} onchange="setConsultationSourceReview(this.checked)"><span><strong>I have reviewed this source</strong><small>I checked the speaker labels, patient statements and missing information.</small></span></label>${!consultationReady()?'<p class="capture-hint">Patient and consent checks are required before confirming source review.</p>':''}`:`<div class="consultation-source-empty"><span class="empty-symbol">${icon('file')}</span><h3>Your conversation source appears here</h3><p>Complete preparation, then run the capture example or load the scripted transcript.</p><ul><li>Speaker labels beside each statement</li><li>Source timestamps retained for review</li><li>No diagnosis or examination findings inferred</li></ul></div>`}</div><div class="panel next-document"><span class="eyebrow">04 / DOCUMENT</span><h2>${state.note.trim()?'Continue the document':'Prepare the first draft'}</h2><p>${state.signed?'A locally reviewed version already exists. Open it to inspect the source or create an amendment.':state.note.trim()?'Continue the existing draft, or prepare a replacement after reviewing the source.':'Review the source before creating an example note. The document will still need a separate review and signature.'}</p>${state.note.trim()?'<button class="primary wide" onclick="nav(\'N\')">Open existing document '+icon('arrow')+'</button>':''}${!state.signed?`<button class="${state.note.trim()?'wide':'primary wide'}" ${!canPrepareConsultationDraft()?'disabled':''} onclick="prepareConsultationDraft()">${state.note.trim()?'Prepare replacement example':'Create example draft'} ${icon('arrow')}</button>`:''}${!state.settings.ai?'<p class="fine">Example drafting is off in workspace settings.</p>':''}<div class="document-checklist"><span>${icon('check')} ${c.reviewed?'Source reviewed locally':'Source review required'}</span><span>${icon('file')} Final document review is a separate step</span></div></div></aside></div>`;
};
// Keep leave/reload behaviour explicit; no unload prompt or automatic upload.
window.addEventListener?.('pagehide',()=>stopConsultationCapture(false));
render();
